const test = require('node:test');
const assert = require('node:assert/strict');
const { reportName } = require('../lib/report-name.cjs');
test('POSIX final component without a suffix argument', () => {
  for (const [p, expected] of [
    ['/srv/out/report.html', 'report.html'],
    ['/srv/out/report.HTML///', 'report.HTML'],
    ['relative/a+b', 'a+b'], ['/', ''], ['', '']
  ]) assert.equal(reportName(p), expected);
});

