const test = require('node:test');
const assert = require('node:assert/strict');
const { reportName } = require('../lib/report-name.cjs');
test('optional literal case-sensitive suffix builds on the POSIX helper', () => {
  for (const [p,s,expected] of [
    ['/srv/out/report.html','.html','report'],
    ['/srv/out/report.HTML','.html','report.HTML'],
    ['/srv/out/report.html///','.html','report'],
    ['/srv/out/a.b.c','.c','a.b'], ['/srv/out/a+b','+b','a'],
    ['a+b','a+b',''], ['x.html','.txt','x.html'], ['name','','name'],
    ['/', '.log', ''], ['', '', ''], ['a.txt', undefined, 'a.txt']
  ]) assert.equal(reportName(p,s),expected);
});

