const { posix } = require('node:path');
function reportName(filePath) { return posix.basename(filePath); }
module.exports = { reportName };

const { posix } = require('node:path');
function reportName(filePath, suffix) { return posix.basename(filePath, suffix); }
module.exports = { reportName };
